<?php
session_start();
require_once('dbstring.php');
require_once('check-login.php');
require_once('user-management-utils.php');
require_once('alumni-utils.php');
if(!um_is_admin_manager()){header('location:index.php');exit();}
alumni_ensure_tables($con);
if(empty($_SESSION['alumni_batch_tool_csrf']))$_SESSION['alumni_batch_tool_csrf']=bin2hex(random_bytes(32));

$batches=array();$batchResult=mysqli_query($con,"SELECT batchid,batch,status FROM tblbatch ORDER BY datetimeentry DESC,batch DESC");while($batchResult&&($batch=mysqli_fetch_assoc($batchResult)))$batches[]=$batch;
$batchId=trim((string)($_POST['batchid']??$_GET['batchid']??''));$selected=null;foreach($batches as $batch){if((string)$batch['batchid']===$batchId){$selected=$batch;break;}}
$summary=null;$success='';$error='';
if($selected){
    $safeBatch=mysqli_real_escape_string($con,$batchId);
    $summaryResult=mysqli_query($con,"SELECT COUNT(DISTINCT su.userid) AS total_students, SUM(LOWER(TRIM(COALESCE(su.status,'')))='alumni') AS already_alumni, SUM(LOWER(TRIM(COALESCE(su.status,'')))<>'alumni') AS to_mark_alumni, SUM(LOWER(TRIM(COALESCE(cl.status,'')))='inactive') AS inactive_class_records, SUM(LOWER(TRIM(COALESCE(cl.status,'')))='graduated') AS graduated_class_records FROM tblclass cl INNER JOIN tblsystemuser su ON su.userid=cl.userid WHERE cl.batchid='$safeBatch' AND su.systemtype='Student'");
    $summary=$summaryResult?mysqli_fetch_assoc($summaryResult):null;
}
if(isset($_POST['run_transfer'])){
    if(!hash_equals($_SESSION['alumni_batch_tool_csrf'],(string)($_POST['csrf']??''))){$error='This confirmation form expired. Please reload and try again.';}
    elseif(!$selected){$error='Select a valid batch first.';}
    elseif(empty($_POST['confirm_transfer'])){$error='Tick the confirmation box before making the transfer.';}
    else{
        $safeBatch=mysqli_real_escape_string($con,$batchId);
        mysqli_begin_transaction($con);
        try{
            $accounts=mysqli_query($con,"UPDATE tblsystemuser su INNER JOIN (SELECT DISTINCT userid FROM tblclass WHERE batchid='$safeBatch') cohort ON cohort.userid=su.userid SET su.status='alumni' WHERE su.systemtype='Student' AND LOWER(TRIM(COALESCE(su.status,'')))<>'alumni'");
            $accountsChanged=$accounts?mysqli_affected_rows($con):0;
            $classes=mysqli_query($con,"UPDATE tblclass SET status='graduated' WHERE batchid='$safeBatch' AND LOWER(TRIM(COALESCE(status,'')))='inactive'");
            $classesChanged=$classes?mysqli_affected_rows($con):0;
            if($accounts===false||$classes===false)throw new Exception('The database update did not finish.');
            mysqli_commit($con);
            $imported=alumni_sync_archived_graduates($con);
            $success='Transfer complete for '.$selected['batch'].'. '.$accountsChanged.' student account(s) were marked Alumni, '.$classesChanged.' inactive final class record(s) were marked Graduated, and '.$imported.' new Alumni profile(s) were added to the approval queue.';
            $_SESSION['alumni_batch_tool_csrf']=bin2hex(random_bytes(32));
            $summaryResult=mysqli_query($con,"SELECT COUNT(DISTINCT su.userid) AS total_students, SUM(LOWER(TRIM(COALESCE(su.status,'')))='alumni') AS already_alumni, SUM(LOWER(TRIM(COALESCE(su.status,'')))<>'alumni') AS to_mark_alumni, SUM(LOWER(TRIM(COALESCE(cl.status,'')))='inactive') AS inactive_class_records, SUM(LOWER(TRIM(COALESCE(cl.status,'')))='graduated') AS graduated_class_records FROM tblclass cl INNER JOIN tblsystemuser su ON su.userid=cl.userid WHERE cl.batchid='$safeBatch' AND su.systemtype='Student'");$summary=$summaryResult?mysqli_fetch_assoc($summaryResult):null;
        }catch(Throwable $exception){mysqli_rollback($con);$error='Nothing was changed because the transfer could not finish: '.$exception->getMessage();}
    }
}
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Graduate Batch to Alumni | AYISEC</title><link rel="icon" type="image/png" href="logo/logo-transparent.png"><style>:root{--n:#102b4b;--t:#08766f;--g:#e3ac36;--bg:#f4f7fb;--line:#dce5ed}*{box-sizing:border-box}body{margin:0;background:var(--bg);font:15px/1.55 Arial,sans-serif;color:#1e293b}.wrap{max-width:880px;margin:auto;padding:42px 18px 70px}.hero{background:linear-gradient(120deg,var(--n),var(--t));border-radius:20px;padding:32px;color:#fff}.hero small{color:#f0ca71;font-weight:bold;letter-spacing:1.2px}.hero h1{font:600 31px Georgia,serif;margin:6px 0}.hero p{margin:0;color:#dcecf0}.card{background:#fff;border:1px solid var(--line);border-radius:16px;padding:24px;margin-top:20px;box-shadow:0 7px 18px #102b4b0d}h2{font:600 23px Georgia,serif;color:var(--n);margin:0 0 8px}.note{color:#64748b}.field{display:block;margin-top:16px;font-size:12px;font-weight:bold;color:#475569}.field select{display:block;width:100%;margin-top:6px;padding:12px;border:1px solid #c8d6e2;border-radius:9px;background:#fff;font:inherit}.summary{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin-top:17px}.summary div{padding:14px;border-radius:10px;background:#f2f7f8}.summary strong{display:block;font-size:24px;color:var(--n)}.confirm{display:flex;gap:9px;align-items:flex-start;margin:19px 0;color:#40546a}.confirm input{margin-top:4px}button,a{display:inline-block;border:0;border-radius:9px;padding:12px 15px;background:var(--t);color:#fff;text-decoration:none;font-weight:bold;cursor:pointer}.secondary{background:#e9f1f6;color:var(--n);margin-left:8px}.danger{background:#a94442}.alert{padding:14px;border-radius:10px;margin-top:18px}.success{background:#e4f8ee;color:#126443}.error{background:#fff0f0;color:#a12626}@media(max-width:600px){.wrap{padding:22px 12px}.hero,.card{padding:21px}.summary{grid-template-columns:1fr}.secondary{margin:8px 0 0}}</style></head><body><main class="wrap"><section class="hero"><small>AYISEC ADMINISTRATION</small><h1>Graduate batch to Alumni</h1><p>This protected tool moves only the selected completed batch into the Alumni pathway. Review the preview before confirming.</p></section><?php if($success!==''){?><p class="alert success"><?php echo alumni_safe($success);?></p><?php }?><?php if($error!==''){?><p class="alert error"><?php echo alumni_safe($error);?></p><?php }?><section class="card"><h2>1. Select the completed batch</h2><p class="note">For your current case, select <b>September 2023</b>.</p><form method="get"><label class="field">Batch<select name="batchid" onchange="this.form.submit()"><option value="">Choose a batch…</option><?php foreach($batches as $batch){?><option value="<?php echo alumni_safe($batch['batchid']);?>" <?php echo $selected&&$selected['batchid']===$batch['batchid']?'selected':'';?>><?php echo alumni_safe($batch['batch']);?> (<?php echo alumni_safe($batch['status']);?>)</option><?php }?></select></label></form><?php if($summary){?><div class="summary"><div><strong><?php echo number_format((int)$summary['total_students']);?></strong>Total students in batch</div><div><strong><?php echo number_format((int)$summary['to_mark_alumni']);?></strong>To mark as Alumni</div><div><strong><?php echo number_format((int)$summary['inactive_class_records']);?></strong>Inactive class records to graduate</div></div></section><section class="card"><h2>2. Confirm the transfer</h2><p class="note">This changes the selected students’ account status to <b>alumni</b>, changes only their inactive class records to <b>graduated</b>, then adds missing profiles to the Alumni approval queue.</p><form method="post"><input type="hidden" name="csrf" value="<?php echo alumni_safe($_SESSION['alumni_batch_tool_csrf']);?>"><input type="hidden" name="batchid" value="<?php echo alumni_safe($selected['batchid']);?>"><label class="confirm"><input type="checkbox" name="confirm_transfer" value="1"> <span>I have confirmed that <b><?php echo alumni_safe($selected['batch']);?></b> is a completed graduating batch and should be moved to Alumni.</span></label><button class="danger" name="run_transfer">Transfer this batch to Alumni</button><a class="secondary" href="alumni-hub.php">Cancel</a></form></section><?php }?></main></body></html>
